const items = $input.all().map(i => i.json);
const lines = items.map(p =>
  `\u2022 ${p.product_code} - ${p.product_name}: ${p.available_stock} left (reorder at ${p.reorder_level})` +
  (p.preferred_supplier_name ? ` — suggest ${p.preferred_supplier_name}` : '')
);
return [{
  json: {
    text: `Reorder digest (${items.length} item${items.length === 1 ? '' : 's'} at or below threshold):\n\n${lines.join('\n')}\n\nReply e.g. "reorder RM-CRCA-2MM" to raise a PR for one item.`,
    items,
  },
}];

const text = ($json.message.text || '').trim();
const match = text.match(/^reorder\s+(\S+)/i);
return [{ json: { ...$json, product_code: match ? match[1].toUpperCase() : null } }];
